package com.example.text;

import java.util.concurrent.atomic.AtomicLong;
import java.util.List;
import java.util.Map;

/** Runs `Nums` and its Rust port side by side. Generated by carcinize: call it in place of `Nums`. */
public final class NumsShadow {
    private NumsShadow() {}

    private static final String MODE = System.getProperty("carcinize.mode", "shadow");
    public static final AtomicLong CALLS = new AtomicLong();
    public static final AtomicLong MISMATCHES = new AtomicLong();

    private static void compare(String name, Object expected, Object actual) {
        CALLS.incrementAndGet();
        if (actual instanceof Throwable || !carcinize.CarcinizeJson.write(expected).equals(carcinize.CarcinizeJson.write(actual))) {
            if (MISMATCHES.incrementAndGet() <= 10) {
                System.err.println("[carcinize] mismatch in " + name + ": expected " + expected + ", got " + actual);
            }
        }
    }

    public static long gcd(long a, long b) {
        if (MODE.equals("new")) {
            return (Long) carcinize.TextRsNative.invoke("gcd", new carcinize.CarcinizeJson.TypeRef<Long>() {}.type(), a, b);
        }
        long expected = Nums.gcd(a, b);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("gcd", new carcinize.CarcinizeJson.TypeRef<Long>() {}.type(), a, b);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("gcd", expected, actual);
        }
        return expected;
    }

    public static double mean(double[] values) {
        if (MODE.equals("new")) {
            return (Double) carcinize.TextRsNative.invoke("mean", new carcinize.CarcinizeJson.TypeRef<Double>() {}.type(), values);
        }
        double expected = Nums.mean(values);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("mean", new carcinize.CarcinizeJson.TypeRef<Double>() {}.type(), values);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("mean", expected, actual);
        }
        return expected;
    }

    public static int pages(int total, int perPage) {
        if (MODE.equals("new")) {
            return (Integer) carcinize.TextRsNative.invoke("pages", new carcinize.CarcinizeJson.TypeRef<Integer>() {}.type(), total, perPage);
        }
        int expected = Nums.pages(total, perPage);
        if (!MODE.equals("old")) {
            Object actual;
            try {
                actual = carcinize.TextRsNative.invoke("pages", new carcinize.CarcinizeJson.TypeRef<Integer>() {}.type(), total, perPage);
            } catch (RuntimeException e) {
                actual = e;
            }
            compare("pages", expected, actual);
        }
        return expected;
    }
}
